typedef void (*TcpIp_IcmpV6MsgHandlerCbkType)(uint8 Type, uint8 Code, IPV6_P2C(uint8) OrigPktPtr, uint16 OrigPktLen, IPV6_P2C(uint8) MultiPartExtPtr, uint16 MultiPartExtLen);
